CREATE TABLE IF NOT EXISTS campaigns ( id TEXT PRIMARY KEY, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Agreed', loc TEXT NOT NULL DEFAULT '[]', deal TEXT, retarget TEXT, start_date TEXT, end_date TEXT, notes TEXT, rotation TEXT, deleted INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')) ); CREATE INDEX IF NOT EXISTS idx_campaigns_deleted ON campaigns(deleted); CREATE TABLE IF NOT EXISTS marketing_ideas ( id TEXT PRIMARY KEY, text TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')) ); CREATE TABLE IF NOT EXISTS marketing_calendar ( id TEXT PRIMARY KEY, name TEXT NOT NULL, date TEXT NOT NULL, end_date TEXT, type TEXT, status TEXT, notes TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')) ); CREATE INDEX IF NOT EXISTS idx_marketing_calendar_date ON marketing_calendar(date);
